import{_ as d,o as a,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"ভোক্তা সুরক্ষা আইন","description":"","frontmatter":{},"headers":[],"relativePath":"bn/42-消费者保护法.md","filePath":"bn/42-消费者保护法.md","lastUpdated":1789183869000}'),e={name:"bn/42-消费者保护法.md"};function i(o,t,h,n,s,_){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="ভোক্তা-সুরক্ষা-আইন" tabindex="-1">ভোক্তা সুরক্ষা আইন <a class="header-anchor" href="#ভোক্তা-সুরক্ষা-আইন" aria-label="Permalink to &quot;ভোক্তা সুরক্ষা আইন&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>42</td></tr><tr><td>মডিউল</td><td>আইনি ব্যবস্থা এবং প্রশাসনিক কাঠামো</td></tr><tr><td>মূল কীওয়ার্ড</td><td>ভোক্তা অধিকার, ন্যায্য লেনদেন, প্রতারণা বিরোধী, পণ্যের দায়বদ্ধতা, সিম্বায়োসিস বাজার</td></tr></tbody></table><h2 id="_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-প্রযোজ্যতার-সীমা" tabindex="-1">1. আইন প্রণয়নের উদ্দেশ্য এবং প্রযোজ্যতার সীমা <a class="header-anchor" href="#_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-প্রযোজ্যতার-সীমা" aria-label="Permalink to &quot;1. আইন প্রণয়নের উদ্দেশ্য এবং প্রযোজ্যতার সীমা&quot;">​</a></h2><p>《ভোক্তা সুরক্ষা আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার আইনি ব্যবস্থার মূল আইনগুলির মধ্যে একটি, এবং 《সিম্বায়োসিস শ্রম আইন》 এর সাথে মিলে অর্থনৈতিক জীবনের দুটি মূল স্তম্ভ গঠন করে। এই আইনের উদ্দেশ্য হল হেঙ্গুয়ানঝৌর ভেতরে সমস্ত ভোক্তার বৈধ অধিকার সুরক্ষা করা, বাজার লেনদেনের আচরণকে নিয়ন্ত্রণ করা, ন্যায্য, সততা, সিম্বায়োসিস বাজারের ব্যবস্থা বজায় রাখা, এবং লুঠেরা বাণিজ্যিক আচরণের সকল প্রাণের অধিকারে আক্রমণ প্রতিরোধ করা।</p><p>এই আইন হেঙ্গুয়ানঝৌর ভেতরে ব্যক্তিগত বা পারিবারিক জীবনের চাহিদা পূরণের জন্য পণ্য ক্রয়, ব্যবহার বা সেবা গ্রহণকারী সমস্ত ভোক্তা, এবং ভোক্তাদের কাছে পণ্য বা সেবা প্রদানকারী ব্যবসায়ীদের ক্ষেত্রে প্রযোজ্য। আন্তঃ位面 লেনদেনেও এই আইন প্রযোজ্য, কিন্তু位面 পার্থক্য অনুযায়ী বাস্তবায়নের বিস্তারিত নিয়ম তৈরি করা যায়।</p><h2 id="_2-ভোক্তার-মৌলিক-অধিকার" tabindex="-1">2. ভোক্তার মৌলিক অধিকার <a class="header-anchor" href="#_2-ভোক্তার-মৌলিক-অধিকার" aria-label="Permalink to &quot;2. ভোক্তার মৌলিক অধিকার&quot;">​</a></h2><p>এই আইন ভোক্তাদের নিম্নলিখিত নয়টি মৌলিক অধিকার প্রদান করে:</p><table tabindex="0"><thead><tr><th>অধিকার</th><th>অন্তর্নিহিত অর্থ</th></tr></thead><tbody><tr><td>নিরাপত্তা নিশ্চয়তা অধিকার</td><td>ভোক্তা পণ্য ক্রয়, ব্যবহার এবং সেবা গ্রহণের সময় ব্যক্তিগত, সম্পত্তির নিরাপত্তা ক্ষতিগ্রস্ত না হওয়ার অধিকার রাখে</td></tr><tr><td>সত্য তথ্য জানার অধিকার</td><td>ভোক্তা তার ক্রয়কৃত, ব্যবহৃত পণ্য বা গৃহীত সেবার প্রকৃত অবস্থা জানার অধিকার রাখে, উপাদান, কার্যকারিতা, ঝুঁকি ইত্যাদি সহ</td></tr><tr><td>স্বায়ত্তশাসিত পছন্দ অধিকার</td><td>ভোক্তা স্বাধীনভাবে পণ্য বা সেবা বেছে নেওয়ার অধিকার রাখে, তুলনা, সনাক্তকরণ এবং বাছাই করার অধিকার রাখে, এবং জোরপূর্বক লেনদেন প্রত্যাখ্যান করতে পারে</td></tr><tr><td>ন্যায্য লেনদেন অধিকার</td><td>ভোক্তা মান নিশ্চয়তা, যুক্তিসঙ্গত মূল্য, সঠিক পরিমাপ ইত্যাদি ন্যায্য লেনদেনের শর্ত পাওয়ার অধিকার রাখে</td></tr><tr><td>আইন অনুযায়ী ক্ষতিপূরণ অধিকার</td><td>ভোক্তা পণ্য ক্রয়, ব্যবহার বা সেবা গ্রহণের কারণে ব্যক্তিগত, সম্পত্তির ক্ষতি গ্রস্ত হলে, আইন অনুযায়ী ক্ষতিপূরণ পাওয়ার অধিকার রাখে</td></tr><tr><td>সংঘ গঠন করে অধিকার রক্ষা করার অধিকার</td><td>ভোক্তা আইন অনুযায়ী ভোক্তা সংগঠন গঠন বা যোগ দেওয়ার অধিকার রাখে, এবং নিজের বৈধ অধিকার রক্ষা করতে পারে</td></tr><tr><td>জ্ঞান অর্জনের অধিকার</td><td>ভোক্তা ভোগ এবং ভোক্তা অধিকার সুরক্ষা সম্পর্কিত জ্ঞান এবং তথ্য অর্জনের অধিকার রাখে</td></tr><tr><td>সম্মানের অধিকার</td><td>ভোক্তা পণ্য ক্রয়, ব্যবহার এবং সেবা গ্রহণের সময় ব্যক্তিগত মর্যাদা, জাতীয় রীতিনীতি সম্মানের অধিকার রাখে</td></tr><tr><td>তদারকি অধিকার</td><td>ভোক্তা পণ্য এবং সেবা এবং ভোক্তা অধিকার সুরক্ষার কাজের তদারকি করার, সমালোচনা এবং পরামর্শ প্রদানের অধিকার রাখে</td></tr></tbody></table><h2 id="_3-ব্যবসায়ীর-কর্তব্য" tabindex="-1">3. ব্যবসায়ীর কর্তব্য <a class="header-anchor" href="#_3-ব্যবসায়ীর-কর্তব্য" aria-label="Permalink to &quot;3. ব্যবসায়ীর কর্তব্য&quot;">​</a></h2><p>ব্যবসায়ী ভোক্তাদের কাছে পণ্য বা সেবা প্রদানের সময়, নিম্নলিখিত কর্তব্য পালন করতে হবে:</p><ol><li><strong>আইন অনুযায়ী ব্যবসা করার কর্তব্য</strong>: ব্যবসায়ীকে অবশ্যই সংবিধান এবং আইন মেনে চলতে হবে, এবং অনুমোদিত ব্যবসার সীমার মধ্যে ব্যবসায়িক কার্যক্রম চালাতে হবে।</li><li><strong>নিরাপত্তা নিশ্চয়তা কর্তব্য</strong>: ব্যবসায়ীকে তার প্রদত্ত পণ্য বা সেবা ব্যক্তিগত, সম্পত্তির নিরাপত্তা নিশ্চিত করার প্রয়োজনীয়তা পূরণ করে তা নিশ্চিত করতে হবে, এবং সম্ভাব্য নিরাপত্তা বিপজ্জনক পণ্য এবং সেবা সম্পর্কে প্রকৃত ব্যাখ্যা এবং স্পষ্ট সতর্কবার্য দিতে হবে।</li><li><strong>প্রকৃত তথ্য কর্তব্য</strong>: ব্যবসায়ীকে ভোক্তাদের কাছে পণ্য বা সেবা সম্পর্কিত প্রকৃত তথ্য প্রদান করতে হবে, এবং মিথ্যা বা বিভ্রান্তিকর প্রচার করা যাবে না। সাধনা শ্রেণীর পণ্য এবং সেবা অবশ্যই কার্যকারিতার সীমা এবং সম্ভাব্য ঝুঁকি সত্যিকারেরভাবে চিহ্নিত করতে হবে।</li><li><strong>মান নিশ্চয়তা কর্তব্য</strong>: ব্যবসায়ীকে স্বাভাবিকভাবে পণ্য ব্যবহার বা সেবা গ্রহণের অবস্থায়, তার প্রদত্ত পণ্য বা সেবার থাকা উচিত এমন মান, কার্যকারিতা, ব্যবহার এবং মেয়াদ নিশ্চিত করতে হবে।</li><li><strong>ন্যায্য লেনদেন কর্তব্য</strong>: ব্যবসায়ী ফরম্যাট শর্ত, নোটিশ, ঘোষণা, দোকানের বিজ্ঞপ্তি ইত্যাদি উপায়ে ভোক্তার অধিকার বাদ বা সীমিত করা, ব্যবসায়ীর দায়বদ্ধতা হ্রাস বা মুক্ত করা, ভোক্তার দায়বদ্ধতা বাড়ানো ইত্যাদি ভোক্তার প্রতি অন্যায্য, অযুক্তিসঙ্গত বিধান তৈরি করতে পারবে না।</li><li><strong>বিক্রয়োত্তর সেবা কর্তব্য</strong>: ব্যবসায়ীকে রাষ্ট্রের বিধান বা ভোক্তার সাথে চুক্তি অনুযায়ী, মেরামত, পরিবর্তন, ফেরত এবং অন্যান্য বিক্রয়োত্তর সেবার দায়বদ্ধতা গ্রহণ করতে হবে।</li><li><strong>গোপনীয়তা সুরক্ষা কর্তব্য</strong>: ব্যবসায়ীকে ভোক্তার ব্যক্তিগত তথ্য এবং চেতনা ডেটা সুরক্ষা করতে হবে, এবং ভোক্তার সম্মতি ছাড়া সংগ্রহ, ব্যবহার বা ফাঁস করা যাবে না।</li></ol><h2 id="_4-বিবাদ-সমাধান-এবং-আইনি-দায়বদ্ধতা" tabindex="-1">4. বিবাদ সমাধান এবং আইনি দায়বদ্ধতা <a class="header-anchor" href="#_4-বিবাদ-সমাধান-এবং-আইনি-দায়বদ্ধতা" aria-label="Permalink to &quot;4. বিবাদ সমাধান এবং আইনি দায়বদ্ধতা&quot;">​</a></h2><p>ভোক্তা এবং ব্যবসায়ীর মধ্যে ভোক্তা অধিকার বিবাদ দেখা দিলে, নিম্নলিখিত উপায়ে সমাধান করা যায়:</p><ul><li>ব্যবসায়ীর সাথে আলোচনা করে সমাধান</li><li>ভোক্তা সংগঠনকে মধ্যস্থতা করার জন্য অনুরোধ করা</li><li>সম্পর্কিত প্রশাসনিক বিভাগে অভিযোগ করা</li><li>ব্যবসায়ীর সাথে চুক্তি করা সালিশ চুক্তি অনুযায়ী সালিশ প্রতিষ্ঠানে সালিশের জন্য আবেদন করা</li><li>সিম্বায়োসিস আদালতে মামলা দায়ের করা</li></ul><p>ব্যবসায়ী এই আইনের বিধান লঙ্ঘন করে ভোক্তার বৈধ অধিকার আক্রমণ করলে, নিম্নলিখিত দায়বদ্ধতা গ্রহণ করতে হবে:</p><table tabindex="0"><thead><tr><th>আইনভঙ্গ কার্যক্রম</th><th>আইনি দায়বদ্ধতা</th></tr></thead><tbody><tr><td>ত্রুটিপূর্ণ পণ্য বা সেবা প্রদান করে ক্ষতি সাধন</td><td>ক্ষতিপূরণের দায়বদ্ধতা গ্রহণ, চিকিৎসা খরচ, কাজ বন্ধের ক্ষতিপূরণ, অক্ষমতা ক্ষতিপূরণ ইত্যাদি সহ</td></tr><tr><td>প্রতারণামূলক আচরণ</td><td>ভোক্তার অনুরোধ অনুযায়ী ক্ষতিপূরণ বাড়ানো, পরিমাণ হল ভোক্তার পণ্য ক্রয় মূল্য বা সেবা গ্রহণ খরচের তিন গুণ</td></tr><tr><td>মিথ্যা প্রচার</td><td>আইনভঙ্গ কার্যক্রম বন্ধ করার নির্দেশ, প্রভাব দূর করা, জরিমানা করা</td></tr><tr><td>জোরপূর্বক লেনদেন</td><td>সংশোধন করার নির্দেশ, অযুক্তিসঙ্গত ফি ফেরত দেওয়া, জরিমানা করা</td></tr><tr><td>ভোক্তার গোপনীয়তা আক্রমণ</td><td>মানসিক ক্ষতি ক্ষতিপূরণ গ্রহণ, গুরুতর অপরাধের ক্ষেত্রে ফৌজদারি দায়বদ্ধতা আরোপ</td></tr></tbody></table><h2 id="_5-ভোক্তা-সংগঠন-এবং-সামাজিক-তদারকি" tabindex="-1">5. ভোক্তা সংগঠন এবং সামাজিক তদারকি <a class="header-anchor" href="#_5-ভোক্তা-সংগঠন-এবং-সামাজিক-তদারকি" aria-label="Permalink to &quot;5. ভোক্তা সংগঠন এবং সামাজিক তদারকি&quot;">​</a></h2><p>রাষ্ট্র সমস্ত সংগঠন এবং ব্যক্তিকে ভোক্তার বৈধ অধিকার ক্ষতিগ্রস্ত করা আচরণের সামাজিক তদারকি করতে উৎসাহিত এবং সহায়তা করে। ভোক্তা সমিতি হল আইন অনুযায়ী প্রতিষ্ঠিত একটি সামাজিক সংগঠন যা পণ্য এবং সেবার সামাজিক তদারকি করে এবং ভোক্তার বৈধ অধিকার সুরক্ষা করে, এবং নিম্নলিখিত কার্য সম্পাদন করে:</p><ol><li>ভোক্তাদের কাছে ভোগ তথ্য এবং পরামর্শ সেবা প্রদান করা</li><li>সম্পর্কিত প্রশাসনিক বিভাগের পণ্য এবং সেবার তদারকি, পরীক্ষায় অংশগ্রহণ করা</li><li>ভোক্তার বৈধ অধিকার সম্পর্কিত সমস্যায়, সম্পর্কিত প্রশাসনিক বিভাগের কাছে প্রতিবেদন, অনুসন্ধান, পরামর্শ প্রদান করা</li><li>ভোক্তার অভিযোগ গ্রহণ করা, এবং অভিযোগের বিষয়ে তদন্ত, মধ্যস্থতা করা</li><li>ভোক্তার বৈধ অধিকার ক্ষতিগ্রস্ত করা আচরণের বিরুদ্ধে, ক্ষতিগ্রস্ত ভোক্তাদের মামলা দায়ের করতে সহায়তা করা</li></ol><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>《ভোক্তা সুরক্ষা আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার বাজার ব্যবস্থার রক্ষক। এটি ভোক্তাদেরকে পর্যাপ্ত অধিকার প্রদান করে, ব্যবসায়ীদের আচরণকে সীমাবদ্ধ করে, এবং বহুমুখী বিবাদ সমাধান ব্যবস্থা স্থাপন করার মাধ্যমে, নিশ্চিত করে যে বাজার লেনদেন ন্যায্য, সততা, সিম্বায়োসিস পথে চলবে, এবং বাণিজ্যিক ক্ষেত্রকে লুঠেরা আচরণের নতুন গর্ত হিসেবে প্রতিরোধ করবে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>40-共生宪法总纲 (সিম্বায়োসিস সংবিধানের মূল নীতি)</li><li>41-共生劳动法 (সিম্বায়োসিস শ্রম আইন)</li><li>47-反垄断法 (একচেটিয়া বিরোধী আইন)</li><li>36-社会结构与阶层流动 (সামাজিক কাঠামো এবং স্তর চলাচল)</li></ul>',23)])])}const p=d(e,[["render",i]]);export{c as __pageData,p as default};
